(window.XZ_MANUAL_CHAPTERS=window.XZ_MANUAL_CHAPTERS||{})["browse"]="<header class=\"mc-head\"><p class=\"mc-eyebrow\">On the player<\/p><h2 class=\"mc-title\" tabindex=\"-1\">Browsing and loading<\/h2><p class=\"mc-lede\">Finding tracks, search, filters, track info, tag lists, playlists and loading to any deck.<\/p><p class=\"applies\" data-applies=\"both\">Applies to <b>MODERN and CLASSIC<\/b><\/p><\/header><p>This chapter covers finding a track and putting it on a deck. MODERN has its own browse screens, built for touch and the rotary encoder. CLASSIC uses the player's own browse screens and adds the key, colours for compatible keys and a few labels to them.<\/p>\n<h3 id=\"m-browsing-in-modern\" data-anchor=\"browsing-in-modern\" data-iface=\"modern\">Browsing in MODERN <span class=\"tag tag--modern\">modern<\/span><\/h3>\n<p>Press <span class=\"xzb\" data-key=\"browse\"><img class=\"xzb-g\" src=\"assets/buttons/browse.svg\" alt=\"\" width=\"79.98\" height=\"32\"><span class=\"xzb-n\">BROWSE<\/span><\/span> or <span class=\"xzb\" data-key=\"tag-list\"><img class=\"xzb-g\" src=\"assets/buttons/tag-list.svg\" alt=\"\" width=\"83.15\" height=\"32\"><span class=\"xzb-n\">TAG LIST<\/span><\/span> to open that list, or hold <span class=\"xzb\" data-key=\"browse\"><img class=\"xzb-g\" src=\"assets/buttons/browse.svg\" alt=\"\" width=\"79.98\" height=\"32\"><span class=\"xzb-n\">BROWSE<\/span><\/span> for SEARCH. PLAYLIST is in the BROWSE category rail and on the SHORTCUT screen. Press <span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span> to go up one level. At the top of a list <span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span> opens SOURCE, where you pick the USB to browse.<\/p>\n<div class=\"mn\" data-iface=\"modern\" role=\"group\" aria-label=\"Browsing in MODERN\"><ol class=\"mn-scenes\"><li data-flow=\"browse-category-folder\" data-video=\"assets/manual/nav/browse-category-folder.mp4\" data-poster=\"assets/manual/nav/browse-category-folder.webp\" data-w=\"1280\" data-h=\"480\" data-seconds=\"5.612\" data-title=\"Browsing in MODERN\"><ol class=\"mn-steps\"><li data-t=\"500\">Press <span class=\"xzb\" data-key=\"browse\"><img class=\"xzb-g\" src=\"assets/buttons/browse.svg\" alt=\"\" width=\"79.98\" height=\"32\"><span class=\"xzb-n\">BROWSE<\/span><\/span><\/li><li data-t=\"1000\">Turn <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span> 7 clicks clockwise, then push it<\/li><li data-t=\"2900\">Turn <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span> 1 click clockwise, then push it<\/li><li data-t=\"3600\">Press <span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span><\/li><li data-t=\"4100\">Press <span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span><\/li><\/ol><\/li><\/ol><\/div>\n<figure class=\"mf\" id=\"f-browse-1\" data-iface=\"modern\"><div class=\"mf-frame\"><div class=\"mf-bar\"><span class=\"mf-label\">BROWSE · TRACK<\/span><\/div><div class=\"mf-stage\"><img src=\"manual/shots/66ddea9e3f8920c4.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"The TRACK category of USB1, sorted by title, with PREVIEW on and a row touched.\"><span class=\"mf-spot\" aria-hidden=\"true\"><\/span><div class=\"mf-marks\" role=\"group\" aria-label=\"Numbered points on the picture\"><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"1\" data-x=\"8.000\" data-y=\"9.583\" aria-label=\"1: Source\" aria-describedby=\"f-browse-1-1\">1<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"2\" data-x=\"7.875\" data-y=\"29.167\" aria-label=\"2: Category rail\" aria-describedby=\"f-browse-1-2\">2<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"3\" data-x=\"11.000\" data-y=\"8.333\" aria-label=\"3: BACK\" aria-describedby=\"f-browse-1-3\">3<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"4\" data-x=\"70.375\" data-y=\"8.333\" aria-label=\"4: PREVIEW\" aria-describedby=\"f-browse-1-4\">4<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"5\" data-x=\"79.375\" data-y=\"8.333\" aria-label=\"5: INFO\" aria-describedby=\"f-browse-1-5\">5<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"6\" data-x=\"45.750\" data-y=\"12.708\" aria-label=\"6: Column title\" aria-describedby=\"f-browse-1-6\">6<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"7\" data-x=\"15.000\" data-y=\"51.042\" aria-label=\"7: Preview\" aria-describedby=\"f-browse-1-7\">7<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"8\" data-x=\"28.750\" data-y=\"27.292\" aria-label=\"8: Played\" aria-describedby=\"f-browse-1-8\">8<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"9\" data-x=\"78.750\" data-y=\"44.167\" aria-label=\"9: On a deck\" aria-describedby=\"f-browse-1-9\">9<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"10\" data-x=\"75.000\" data-y=\"63.750\" aria-label=\"10: LOAD\" aria-describedby=\"f-browse-1-10\">10<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"11\" data-x=\"98.125\" data-y=\"63.750\" aria-label=\"11: Key colour\" aria-describedby=\"f-browse-1-11\">11<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"12\" data-x=\"13.750\" data-y=\"87.083\" aria-label=\"12: Deck strip\" aria-describedby=\"f-browse-1-12\">12<\/button><\/div><\/div><\/div><figcaption>The TRACK category of USB1, sorted by title, with PREVIEW on and a row touched.<\/figcaption><ol class=\"mf-legend\" aria-label=\"What the numbers show\"><li data-n=\"1\" id=\"f-browse-1-1\"><span class=\"mf-chip\" aria-hidden=\"true\">1<\/span><div><b>Source<\/b> <span>The USB you are browsing, in its own colour. Tap to open SOURCE.<\/span><\/div><\/li><li data-n=\"2\" id=\"f-browse-1-2\"><span class=\"mf-chip\" aria-hidden=\"true\">2<\/span><div><b>Category rail<\/b> <span>ARTIST, ALBUM, TRACK, KEY, BPM, GENRE, RATING, COLOR, PLAYLIST, FOLDER, HISTORY and MATCHING. Tap one, or drag the rail to see the rest.<\/span><\/div><\/li><li data-n=\"3\" id=\"f-browse-1-3\"><span class=\"mf-chip\" aria-hidden=\"true\">3<\/span><div><b>BACK<\/b> <span>Goes up one level.<\/span><\/div><\/li><li data-n=\"4\" id=\"f-browse-1-4\"><span class=\"mf-chip\" aria-hidden=\"true\">4<\/span><div><b>PREVIEW<\/b> <span>Shows or hides the preview waveform column.<\/span><\/div><\/li><li data-n=\"5\" id=\"f-browse-1-5\"><span class=\"mf-chip\" aria-hidden=\"true\">5<\/span><div><b>INFO<\/b> <span>Opens the INFO panel for the highlighted track.<\/span><\/div><\/li><li data-n=\"6\" id=\"f-browse-1-6\"><span class=\"mf-chip\" aria-hidden=\"true\">6<\/span><div><b>Column title<\/b> <span>The arrow marks the column the list is sorted by. The number in brackets is how many items the list holds.<\/span><\/div><\/li><li data-n=\"7\" id=\"f-browse-1-7\"><span class=\"mf-chip\" aria-hidden=\"true\">7<\/span><div><b>Preview<\/b> <span>A small waveform of each track, so you can see breaks and builds before you load.<\/span><\/div><\/li><li data-n=\"8\" id=\"f-browse-1-8\"><span class=\"mf-chip\" aria-hidden=\"true\">8<\/span><div><b>Played<\/b> <span>A green note marks a track you have played.<\/span><\/div><\/li><li data-n=\"9\" id=\"f-browse-1-9\"><span class=\"mf-chip\" aria-hidden=\"true\">9<\/span><div><b>On a deck<\/b> <span>A blue number says the track is loaded on that deck.<\/span><\/div><\/li><li data-n=\"10\" id=\"f-browse-1-10\"><span class=\"mf-chip\" aria-hidden=\"true\">10<\/span><div><b>LOAD<\/b> <span>Appears on the row you touched. Tap 1 or 2 to load the track on that deck.<\/span><\/div><\/li><li data-n=\"11\" id=\"f-browse-1-11\"><span class=\"mf-chip\" aria-hidden=\"true\">11<\/span><div><b>Key colour<\/b> <span>Green or amber means the key mixes with the master deck's key.<\/span><\/div><\/li><li data-n=\"12\" id=\"f-browse-1-12\"><span class=\"mf-chip\" aria-hidden=\"true\">12<\/span><div><b>Deck strip<\/b> <span>Both decks' time, overview, tempo, key and BPM stay in view while you browse.<\/span><\/div><\/li><\/ol><\/figure>\n<h4 id=\"m-moving-through-a-list\" data-anchor=\"moving-through-a-list\" data-iface=\"modern\">Moving through a list <span class=\"tag tag--modern\">modern<\/span><\/h4>\n<div class=\"mn\" data-iface=\"modern\" role=\"group\" aria-label=\"Moving through a list\"><ol class=\"mn-scenes\"><li data-flow=\"encoder-list\" data-video=\"assets/manual/nav/encoder-list.mp4\" data-poster=\"assets/manual/nav/encoder-list.webp\" data-w=\"1280\" data-h=\"480\" data-seconds=\"4.012\" data-title=\"Moving through a list\"><ol class=\"mn-steps\"><li data-t=\"500\">Press <span class=\"xzb\" data-key=\"browse\"><img class=\"xzb-g\" src=\"assets/buttons/browse.svg\" alt=\"\" width=\"79.98\" height=\"32\"><span class=\"xzb-n\">BROWSE<\/span><\/span><\/li><li data-t=\"1000\">Push <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span><\/li><li data-t=\"1500\">Turn <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span> 5 clicks clockwise<\/li><li data-t=\"2500\">Press <span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span><\/li><\/ol><\/li><\/ol><\/div>\n<div class=\"table\"><table><thead><tr><th>Control<\/th><th>What it does<\/th><\/tr><\/thead><tbody><tr><td>Turn the encoder<\/td><td>Moves the highlight one row<\/td><\/tr><tr><td>Push the encoder<\/td><td>Opens a folder. On a track, opens the <strong>LOAD TRACK<\/strong> menu: LOAD TO DECK for each deck, in the order of the lanes, CUE / LOOP LIST when the track has memory points and the deck can load at one, and CANCEL. The active deck is highlighted, so a second push loads it there<\/td><\/tr><tr><td>Hold the encoder<\/td><td>Turns letter jump on. Turning then jumps by first letter, or by page where the list has no index. Push or hold again to stop<\/td><\/tr><tr><td>Drag or flick the list<\/td><td>Scrolls<\/td><\/tr><tr><td>Tap a row<\/td><td>Highlights it and shows LOAD<\/td><\/tr><tr><td><span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span><\/td><td>Up one level. At the top, opens SOURCE<\/td><\/tr><tr><td><span class=\"xzb\" data-key=\"menu\"><img class=\"xzb-g\" src=\"assets/buttons/menu.svg\" alt=\"\" width=\"60.86\" height=\"32\"><span class=\"xzb-n\">MENU<\/span><\/span><\/td><td>Opens the list's MENU panel: sort, columns and the track menu<\/td><\/tr><tr><td><span class=\"xzb\" data-key=\"info\"><img class=\"xzb-g\" src=\"assets/buttons/info.svg\" alt=\"\" width=\"54.02\" height=\"32\"><span class=\"xzb-n\">INFO<\/span><\/span><\/td><td>Opens or closes the INFO panel<\/td><\/tr><\/tbody><\/table><\/div>\n<div class=\"mg\" id=\"f-browse-2\" data-iface=\"modern\"><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/6cc6e2e9a449e157.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: PREVIEW off: the PREVIEW OFF tile and the full width for the columns\"><img src=\"manual/shots/6cc6e2e9a449e157.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>PREVIEW off: the PREVIEW OFF tile and the full width for the columns<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/414bc5c9c141f2ad.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: PREVIEW on\"><img src=\"manual/shots/414bc5c9c141f2ad.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>PREVIEW on<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/c2f644aad4746a01.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Letter jump: the letter shows large while you turn\"><img src=\"manual/shots/c2f644aad4746a01.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Letter jump: the letter shows large while you turn<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/414bc5c9c141f2ad.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Page jump in a list with no letter index\"><img src=\"manual/shots/414bc5c9c141f2ad.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Page jump in a list with no letter index<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/465da2e70f780a70.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The highlight near the end of a long list\"><img src=\"manual/shots/465da2e70f780a70.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The highlight near the end of a long list<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/c2f644aad4746a01.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Rows still on their way from the USB stay blank for a moment\"><img src=\"manual/shots/c2f644aad4746a01.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Rows still on their way from the USB stay blank for a moment<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/ada301dce9ddc552.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The PLAYLIST category: folders and playlists\"><img src=\"manual/shots/ada301dce9ddc552.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The PLAYLIST category: folders and playlists<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/b67aaf58ad30a190.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The category rail dragged down to HISTORY and MATCHING\"><img src=\"manual/shots/b67aaf58ad30a190.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The category rail dragged down to HISTORY and MATCHING<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/cafb557f589dfb0c.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Long names are cut to fit their column\"><img src=\"manual/shots/cafb557f589dfb0c.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Long names are cut to fit their column<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/825c810d60bbf204.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: BROWSE before the USB&#x27;s library has been read: LIST NOT READ YET\"><img src=\"manual/shots/825c810d60bbf204.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>BROWSE before the USB's library has been read: LIST NOT READ YET<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/3bf0cba3b6fd4a06.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: PLAYLIST before it has been read\"><img src=\"manual/shots/3bf0cba3b6fd4a06.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>PLAYLIST before it has been read<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/bb6b197f9f33e397.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: TAG LIST before it has been read\"><img src=\"manual/shots/bb6b197f9f33e397.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>TAG LIST before it has been read<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/f2d9cb7e7775bd68.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: SEARCH before the library has been read\"><img src=\"manual/shots/f2d9cb7e7775bd68.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>SEARCH before the library has been read<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/f0b3c20380046054.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Deck 2 empty in the deck strip\"><img src=\"manual/shots/f0b3c20380046054.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Deck 2 empty in the deck strip<\/figcaption><\/figure><\/div>\n<p>The preview column starts hidden. One tap on <strong>PREVIEW<\/strong> shows it, and XZ Mods remembers your choice on the USB (<code>browse_preview<\/code>). PREVIEW is touch only.<\/p>\n<h4 id=\"m-loading-a-track\" data-anchor=\"loading-a-track\" data-iface=\"modern\">Loading a track <span class=\"tag tag--modern\">modern<\/span><\/h4>\n<p>There are three ways to load the highlighted track:<\/p>\n<div class=\"mn\" data-iface=\"modern\" role=\"group\" aria-label=\"Loading a track\"><ol class=\"mn-scenes\"><li data-flow=\"browse-load\" data-video=\"assets/manual/nav/browse-load.mp4\" data-poster=\"assets/manual/nav/browse-load.webp\" data-w=\"1280\" data-h=\"480\" data-seconds=\"4.112\" data-title=\"Loading a track\"><ol class=\"mn-steps\"><li data-t=\"500\">Press <span class=\"xzb\" data-key=\"browse\"><img class=\"xzb-g\" src=\"assets/buttons/browse.svg\" alt=\"\" width=\"79.98\" height=\"32\"><span class=\"xzb-n\">BROWSE<\/span><\/span><\/li><li data-t=\"1000\">Push <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span><\/li><li data-t=\"1500\">Turn <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span> 3 clicks clockwise<\/li><li data-t=\"2100\">Press <span class=\"xzb\" data-key=\"load\"><img class=\"xzb-g\" src=\"assets/buttons/load.svg\" alt=\"\" width=\"100.66\" height=\"32\"><span class=\"xzb-n\">LOAD<\/span><\/span> 1<\/li><li data-t=\"2600\">Press <span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span><\/li><\/ol><\/li><\/ol><\/div>\n<ul><li>Tap the row, then tap <strong>1<\/strong> or <strong>2<\/strong> on its LOAD chip.<\/li><li>Push the encoder twice to load on the active deck, or push, turn to another deck and push.<\/li><li>Press the <span class=\"xzb\" data-key=\"load\"><img class=\"xzb-g\" src=\"assets/buttons/load.svg\" alt=\"\" width=\"100.66\" height=\"32\"><span class=\"xzb-n\">LOAD<\/span><\/span> button of the deck you want.<\/li><\/ul>\n<p>If no track is highlighted, <span class=\"xzb\" data-key=\"load\"><img class=\"xzb-g\" src=\"assets/buttons/load.svg\" alt=\"\" width=\"100.66\" height=\"32\"><span class=\"xzb-n\">LOAD<\/span><\/span> says <strong>SELECT A TRACK, THEN PRESS LOAD<\/strong>. On a screen that is not a track list it says <strong>OPEN A TRACK LIST TO LOAD<\/strong>. To load onto decks 3 and 4, see <a class=\"m-link\" href=\"#manual\" data-chapter=\"four-decks\">Four decks<\/a>.<\/p>\n<p>While the <strong>LOAD TRACK<\/strong> menu is open, a <span class=\"xzb\" data-key=\"load\"><img class=\"xzb-g\" src=\"assets/buttons/load.svg\" alt=\"\" width=\"100.66\" height=\"32\"><span class=\"xzb-n\">LOAD<\/span><\/span> key loads only when the highlighted row names its own deck. Otherwise the first press moves the highlight to that deck, and a second press loads. With <strong>LOAD LOCK<\/strong> on in UTILITY, a playing deck takes no new track: its row is dimmed and the screen says <strong>LOAD LOCK: DECK 1 IS PLAYING<\/strong>, with the deck's number.<\/p>\n<p>For about 30 seconds after you insert a stick, the player itself refuses to load from it. If you load an empty deck 1 or 2 in that time, the screen says <strong>USB STARTING / DECK 1 LOADS WHEN READY<\/strong> and XZ Mods repeats the load until it lands. You do not need to press <span class=\"xzb\" data-key=\"load\"><img class=\"xzb-g\" src=\"assets/buttons/load.svg\" alt=\"\" width=\"100.66\" height=\"32\"><span class=\"xzb-n\">LOAD<\/span><\/span> again. A deck that already has a track is not loaded later by surprise: load it again once the stick is ready.<\/p>\n<div class=\"mg\" id=\"f-browse-3\" data-iface=\"modern\"><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/4cdf346962059d1a.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The same row with deck 2 active: its 2 is highlighted\"><img src=\"manual/shots/4cdf346962059d1a.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The same row with deck 2 active: its 2 is highlighted<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/a6d4c544cb85ea58.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Loading not available on this list: the row highlights without LOAD\"><img src=\"manual/shots/a6d4c544cb85ea58.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Loading not available on this list: the row highlights without LOAD<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/7f277636f8f5fd17.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: SELECT A TRACK, THEN PRESS LOAD\"><img src=\"manual/shots/7f277636f8f5fd17.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>SELECT A TRACK, THEN PRESS LOAD<\/figcaption><\/figure><\/div>\n<h4 id=\"m-info-panel\" data-anchor=\"info-panel\" data-iface=\"modern\">INFO panel <span class=\"tag tag--modern\">modern<\/span><\/h4>\n<p>Press <span class=\"xzb\" data-key=\"info\"><img class=\"xzb-g\" src=\"assets/buttons/info.svg\" alt=\"\" width=\"54.02\" height=\"32\"><span class=\"xzb-n\">INFO<\/span><\/span> or tap <strong>INFO<\/strong> to open a panel with the highlighted track's details beside the list. The list narrows to make room.<\/p>\n<div class=\"mn\" data-iface=\"modern\" role=\"group\" aria-label=\"INFO panel\"><ol class=\"mn-scenes\"><li data-flow=\"browse-rating-edit\" data-video=\"assets/manual/nav/browse-rating-edit.mp4\" data-poster=\"assets/manual/nav/browse-rating-edit.webp\" data-w=\"1280\" data-h=\"480\" data-seconds=\"4.612\" data-title=\"INFO panel\"><ol class=\"mn-steps\"><li data-t=\"500\">Press <span class=\"xzb\" data-key=\"info\"><img class=\"xzb-g\" src=\"assets/buttons/info.svg\" alt=\"\" width=\"54.02\" height=\"32\"><span class=\"xzb-n\">INFO<\/span><\/span><\/li><li data-t=\"1000\">Tap the screen<\/li><li data-t=\"1520\">Tap the screen<\/li><li data-t=\"2040\">Tap the screen<\/li><li data-t=\"2560\">Tap the screen<\/li><li data-t=\"3080\">Tap the screen<\/li><\/ol><\/li><\/ol><\/div>\n<div class=\"mg\" id=\"f-browse-4\" data-iface=\"modern\"><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/c9862d6b1f293cf8.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The INFO panel: BPM, KEY, TIME, RATING, COLOR, PLAYED and ON DECK\"><img src=\"manual/shots/c9862d6b1f293cf8.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The INFO panel: BPM, KEY, TIME, RATING, COLOR, PLAYED and ON DECK<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/f9fb64765a748a2b.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The INFO panel opened with INFO while keys are colour coded\"><img src=\"manual/shots/f9fb64765a748a2b.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The INFO panel opened with <span class=\"xzb\" data-key=\"info\"><img class=\"xzb-g\" src=\"assets/buttons/info.svg\" alt=\"\" width=\"54.02\" height=\"32\"><span class=\"xzb-n\">INFO<\/span><\/span> while keys are colour coded<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/388c809a43aa73f7.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Keys coloured against deck 1&#x27;s Fm\"><img src=\"manual/shots/388c809a43aa73f7.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Keys coloured against deck 1's Fm<\/figcaption><\/figure><\/div>\n<h4 id=\"m-sort-columns-and-the-track-menu\" data-anchor=\"sort-columns-and-the-track-menu\" data-iface=\"modern\">Sort, columns and the track menu <span class=\"tag tag--modern\">modern<\/span><\/h4>\n<p>Press <span class=\"xzb\" data-key=\"menu\"><img class=\"xzb-g\" src=\"assets/buttons/menu.svg\" alt=\"\" width=\"60.86\" height=\"32\"><span class=\"xzb-n\">MENU<\/span><\/span> or tap a column title. The MENU panel opens on the right with the sort order, the columns to show, and the actions for the highlighted track.<\/p>\n<div class=\"mn\" data-iface=\"modern\" role=\"group\" aria-label=\"Sort, columns and the track menu\"><ol class=\"mn-scenes\"><li data-flow=\"browse-cue-loop-load\" data-video=\"assets/manual/nav/browse-cue-loop-load.mp4\" data-poster=\"assets/manual/nav/browse-cue-loop-load.webp\" data-w=\"1280\" data-h=\"480\" data-seconds=\"4.052\" data-title=\"Sort, columns and the track menu\"><ol class=\"mn-steps\"><li data-t=\"500\">Press <span class=\"xzb\" data-key=\"browse\"><img class=\"xzb-g\" src=\"assets/buttons/browse.svg\" alt=\"\" width=\"79.98\" height=\"32\"><span class=\"xzb-n\">BROWSE<\/span><\/span><\/li><li data-t=\"1000\">Push <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span><\/li><li data-t=\"1500\">Press <span class=\"xzb\" data-key=\"menu\"><img class=\"xzb-g\" src=\"assets/buttons/menu.svg\" alt=\"\" width=\"60.86\" height=\"32\"><span class=\"xzb-n\">MENU<\/span><\/span><\/li><li data-t=\"2000\">Tap <strong>CUE/LOOP LIST<\/strong><\/li><li data-t=\"2520\">Tap <strong>INTRO CUE<\/strong><\/li><\/ol><\/li><\/ol><\/div>\n<figure class=\"mf\" id=\"f-browse-5\" data-iface=\"modern\"><div class=\"mf-frame\"><div class=\"mf-bar\"><span class=\"mf-label\">BROWSE · MENU<\/span><\/div><div class=\"mf-stage\"><img src=\"manual/shots/88d9c229f00a3443.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"The MENU panel on a track list, with three tracks already in the tag list.\"><span class=\"mf-spot\" aria-hidden=\"true\"><\/span><div class=\"mf-marks\" role=\"group\" aria-label=\"Numbered points on the picture\"><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"1\" data-x=\"75.000\" data-y=\"20.833\" aria-label=\"1: TRACK\" aria-describedby=\"f-browse-5-1\">1<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"2\" data-x=\"87.500\" data-y=\"27.083\" aria-label=\"2: ADD TO TAG LIST\" aria-describedby=\"f-browse-5-2\">2<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"3\" data-x=\"86.250\" data-y=\"34.167\" aria-label=\"3: CUE/LOOP LIST\" aria-describedby=\"f-browse-5-3\">3<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"4\" data-x=\"86.250\" data-y=\"41.250\" aria-label=\"4: MARK PLAYED\" aria-describedby=\"f-browse-5-4\">4<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"5\" data-x=\"81.250\" data-y=\"55.417\" aria-label=\"5: SEARCH\" aria-describedby=\"f-browse-5-5\">5<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"6\" data-x=\"49.375\" data-y=\"31.250\" aria-label=\"6: Tag marks\" aria-describedby=\"f-browse-5-6\">6<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"7\" data-x=\"97.000\" data-y=\"8.333\" aria-label=\"7: Close\" aria-describedby=\"f-browse-5-7\">7<\/button><\/div><\/div><\/div><figcaption>The MENU panel on a track list, with three tracks already in the tag list.<\/figcaption><ol class=\"mf-legend\" aria-label=\"What the numbers show\"><li data-n=\"1\" id=\"f-browse-5-1\"><span class=\"mf-chip\" aria-hidden=\"true\">1<\/span><div><b>TRACK<\/b> <span>Actions for the highlighted track.<\/span><\/div><\/li><li data-n=\"2\" id=\"f-browse-5-2\"><span class=\"mf-chip\" aria-hidden=\"true\">2<\/span><div><b>ADD TO TAG LIST<\/b> <span>Adds the track to the tag list. On a track already in it this reads REMOVE FROM TAG LIST.<\/span><\/div><\/li><li data-n=\"3\" id=\"f-browse-5-3\"><span class=\"mf-chip\" aria-hidden=\"true\">3<\/span><div><b>CUE/LOOP LIST<\/b> <span>Not on the player in this version.<\/span><\/div><\/li><li data-n=\"4\" id=\"f-browse-5-4\"><span class=\"mf-chip\" aria-hidden=\"true\">4<\/span><div><b>MARK PLAYED<\/b> <span>Marks the track played. A played track offers MARK UNPLAYED.<\/span><\/div><\/li><li data-n=\"5\" id=\"f-browse-5-5\"><span class=\"mf-chip\" aria-hidden=\"true\">5<\/span><div><b>SEARCH<\/b> <span>Opens SEARCH.<\/span><\/div><\/li><li data-n=\"6\" id=\"f-browse-5-6\"><span class=\"mf-chip\" aria-hidden=\"true\">6<\/span><div><b>Tag marks<\/b> <span>Tracks in the tag list carry a check mark.<\/span><\/div><\/li><li data-n=\"7\" id=\"f-browse-5-7\"><span class=\"mf-chip\" aria-hidden=\"true\">7<\/span><div><b>Close<\/b> <span>Closes the panel. <span class=\"xzb\" data-key=\"menu\"><img class=\"xzb-g\" src=\"assets/buttons/menu.svg\" alt=\"\" width=\"60.86\" height=\"32\"><span class=\"xzb-n\">MENU<\/span><\/span> and <span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span> close it too.<\/span><\/div><\/li><\/ol><\/figure>\n<div class=\"mg\" id=\"f-browse-6\" data-iface=\"modern\"><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/ce35d5357510a6cc.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Sort by: one choice at a time\"><img src=\"manual/shots/ce35d5357510a6cc.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Sort by: one choice at a time<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/63ddfb527b543e8f.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: COLUMNS: tick the columns the list shows\"><img src=\"manual/shots/63ddfb527b543e8f.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>COLUMNS: tick the columns the list shows<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/aa1f9666bbabd762.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Six columns with PREVIEW off, sorted by BPM, highest first\"><img src=\"manual/shots/aa1f9666bbabd762.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Six columns with PREVIEW off, sorted by BPM, highest first<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/fb53f17e3e1d439a.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: COLOR and TIME columns\"><img src=\"manual/shots/fb53f17e3e1d439a.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>COLOR and TIME columns<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/58aeb2773666d0fd.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Check marks on tracks in the tag list\"><img src=\"manual/shots/58aeb2773666d0fd.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Check marks on tracks in the tag list<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/bbc680c6f4c1ce0c.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: HISTORY: ADD ALL TO TAG LIST, DELETE HISTORY and DELETE ALL HISTORIES\"><img src=\"manual/shots/bbc680c6f4c1ce0c.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>HISTORY: ADD ALL TO TAG LIST, DELETE HISTORY and DELETE ALL HISTORIES<\/figcaption><\/figure><\/div>\n<h4 id=\"m-filter\" data-anchor=\"filter\" data-iface=\"modern\">Filter <span class=\"tag tag--modern\">modern<\/span><\/h4>\n<p>Tap <strong>FILTER<\/strong> to narrow the list without leaving it. The filters stay on while you move between categories, and a chip in the header says which are on.<\/p>\n<div class=\"mn\" data-iface=\"modern\" role=\"group\" aria-label=\"Filter\"><ol class=\"mn-scenes\"><li data-flow=\"filter\" data-video=\"assets/manual/nav/filter.mp4\" data-poster=\"assets/manual/nav/filter.webp\" data-w=\"1280\" data-h=\"480\" data-seconds=\"3.912\" data-title=\"Filter\"><ol class=\"mn-steps\"><li data-t=\"500\">Press <span class=\"xzb\" data-key=\"browse\"><img class=\"xzb-g\" src=\"assets/buttons/browse.svg\" alt=\"\" width=\"79.98\" height=\"32\"><span class=\"xzb-n\">BROWSE<\/span><\/span><\/li><li data-t=\"1000\">Press <span class=\"xzb\" data-key=\"track-filter\"><img class=\"xzb-g\" src=\"assets/buttons/track-filter.svg\" alt=\"\" width=\"140.92\" height=\"32\"><span class=\"xzb-n\">TRACK FILTER<\/span><\/span><\/li><li data-t=\"1500\">Turn <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span> 2 clicks clockwise, then push it<\/li><li data-t=\"2400\">Press <span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span><\/li><\/ol><\/li><\/ol><\/div>\n<div class=\"table\"><table><thead><tr><th>Filter<\/th><th>What it keeps<\/th><\/tr><\/thead><tbody><tr><td>BPM<\/td><td>Tracks within a range of the master deck's BPM, for example MASTER ±6<\/td><\/tr><tr><td>MATCH MASTER KEY<\/td><td>Tracks whose key mixes with the master deck's key<\/td><\/tr><tr><td>AT LEAST<\/td><td>Tracks rated at least that many stars<\/td><\/tr><tr><td>COLOR<\/td><td>Tracks with any of the colours you tick<\/td><\/tr><tr><td>MY TAG<\/td><td>Not available yet<\/td><\/tr><\/tbody><\/table><\/div>\n<p><strong>CLEAR ALL FILTERS<\/strong> in the panel, or a tap on the chip, turns every filter off. Filters that compare with the master deck need one. Without it you see <strong>NO MASTER DECK: BPM FILTER OFF<\/strong> or <strong>NO MASTER KEY: KEY FILTER OFF<\/strong>.<\/p>\n<div class=\"mg\" id=\"f-browse-7\" data-iface=\"modern\"><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/890db043f557bbae.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: TRACK FILTER with BPM, key, rating and colour filters on\"><img src=\"manual/shots/890db043f557bbae.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>TRACK FILTER with BPM, key, rating and colour filters on<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/e8249bcdc5df42b2.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The filter chip in the header. Tap it to clear every filter\"><img src=\"manual/shots/e8249bcdc5df42b2.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The filter chip in the header. Tap it to clear every filter<\/figcaption><\/figure><\/div>\n<h4 id=\"m-search\" data-anchor=\"search\" data-iface=\"modern\">Search <span class=\"tag tag--modern\">modern<\/span><\/h4>\n<p>Hold <span class=\"xzb\" data-key=\"browse\"><img class=\"xzb-g\" src=\"assets/buttons/browse.svg\" alt=\"\" width=\"79.98\" height=\"32\"><span class=\"xzb-n\">BROWSE<\/span><\/span> (SEARCH is printed above it), or tap SEARCH on the SHORTCUT screen. Type on the keyboard and the list updates as you type. <strong>SEARCH<\/strong> puts the keyboard away so you can scroll the results. <strong>DELETE<\/strong> removes a letter and <strong>CLEAR<\/strong> empties the field.<\/p>\n<div class=\"mn\" data-iface=\"modern\" role=\"group\" aria-label=\"Search\"><ol class=\"mn-scenes\"><li data-flow=\"search\" data-video=\"assets/manual/nav/search.mp4\" data-poster=\"assets/manual/nav/search.webp\" data-w=\"1280\" data-h=\"480\" data-seconds=\"4.452\" data-title=\"Search\"><ol class=\"mn-steps\"><li data-t=\"500\">Hold <span class=\"xzb\" data-key=\"browse\"><img class=\"xzb-g\" src=\"assets/buttons/browse.svg\" alt=\"\" width=\"79.98\" height=\"32\"><span class=\"xzb-n\">BROWSE<\/span><\/span> for a second<\/li><li data-t=\"2000\">Tap <strong>A<\/strong><\/li><li data-t=\"2520\">Tap <strong>B<\/strong><\/li><li data-t=\"3040\">Turn <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span> 2 clicks clockwise<\/li><\/ol><\/li><\/ol><\/div>\n<figure class=\"mf\" id=\"f-browse-8\" data-iface=\"modern\"><div class=\"mf-frame\"><div class=\"mf-bar\"><span class=\"mf-label\">SEARCH<\/span><\/div><div class=\"mf-stage\"><img src=\"manual/shots/98111f66a5d394c5.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"Typing NEON. Eleven tracks match so far.\"><span class=\"mf-spot\" aria-hidden=\"true\"><\/span><div class=\"mf-marks\" role=\"group\" aria-label=\"Numbered points on the picture\"><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"1\" data-x=\"62.500\" data-y=\"3.750\" aria-label=\"1: Search field\" aria-describedby=\"f-browse-8-1\">1<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"2\" data-x=\"28.125\" data-y=\"12.708\" aria-label=\"2: Count\" aria-describedby=\"f-browse-8-2\">2<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"3\" data-x=\"90.000\" data-y=\"67.917\" aria-label=\"3: SEARCH\" aria-describedby=\"f-browse-8-3\">3<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"4\" data-x=\"90.750\" data-y=\"48.333\" aria-label=\"4: DELETE\" aria-describedby=\"f-browse-8-4\">4<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"5\" data-x=\"50.000\" data-y=\"85.417\" aria-label=\"5: Key\" aria-describedby=\"f-browse-8-5\">5<\/button><\/div><\/div><\/div><figcaption>Typing NEON. Eleven tracks match so far.<\/figcaption><ol class=\"mf-legend\" aria-label=\"What the numbers show\"><li data-n=\"1\" id=\"f-browse-8-1\"><span class=\"mf-chip\" aria-hidden=\"true\">1<\/span><div><b>Search field<\/b> <span>What you have typed.<\/span><\/div><\/li><li data-n=\"2\" id=\"f-browse-8-2\"><span class=\"mf-chip\" aria-hidden=\"true\">2<\/span><div><b>Count<\/b> <span>How many tracks match.<\/span><\/div><\/li><li data-n=\"3\" id=\"f-browse-8-3\"><span class=\"mf-chip\" aria-hidden=\"true\">3<\/span><div><b>SEARCH<\/b> <span>Puts the keyboard away and moves to the results.<\/span><\/div><\/li><li data-n=\"4\" id=\"f-browse-8-4\"><span class=\"mf-chip\" aria-hidden=\"true\">4<\/span><div><b>DELETE<\/b> <span>Removes the last letter.<\/span><\/div><\/li><li data-n=\"5\" id=\"f-browse-8-5\"><span class=\"mf-chip\" aria-hidden=\"true\">5<\/span><div><b>Key<\/b> <span>The key you touched is outlined.<\/span><\/div><\/li><\/ol><\/figure>\n<div class=\"mg\" id=\"f-browse-9\" data-iface=\"modern\"><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/e7fe4271bd031ffc.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: SEARCH before you type\"><img src=\"manual/shots/e7fe4271bd031ffc.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>SEARCH before you type<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/1a37409da180aed2.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The results with the keyboard put away\"><img src=\"manual/shots/1a37409da180aed2.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The results with the keyboard put away<\/figcaption><\/figure><\/div>\n<h4 id=\"m-tag-list\" data-anchor=\"tag-list\" data-iface=\"modern\">Tag list <span class=\"tag tag--modern\">modern<\/span><\/h4>\n<p>The tag list is a quick list of tracks you want to play next. It holds up to 100 tracks and shows how many it has in the header. XZ Mods keeps it on the USB in <code>XZMODS/playlists.txt<\/code>, with your playlist changes. To add a track, use ADD TO TAG LIST in the <span class=\"xzb\" data-key=\"menu\"><img class=\"xzb-g\" src=\"assets/buttons/menu.svg\" alt=\"\" width=\"60.86\" height=\"32\"><span class=\"xzb-n\">MENU<\/span><\/span> panel. To add a whole folder, highlight it and use ADD ALL TO TAG LIST.<\/p>\n<div class=\"mn\" data-iface=\"modern\" role=\"group\" aria-label=\"Tag list\"><ol class=\"mn-scenes\"><li data-flow=\"tag-list\" data-video=\"assets/manual/nav/tag-list.mp4\" data-poster=\"assets/manual/nav/tag-list.webp\" data-w=\"1280\" data-h=\"480\" data-seconds=\"3.412\" data-title=\"Tag list\"><ol class=\"mn-steps\"><li data-t=\"500\">Press <span class=\"xzb\" data-key=\"tag-list\"><img class=\"xzb-g\" src=\"assets/buttons/tag-list.svg\" alt=\"\" width=\"83.15\" height=\"32\"><span class=\"xzb-n\">TAG LIST<\/span><\/span><\/li><li data-t=\"1000\">Turn <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span> 2 clicks clockwise<\/li><li data-t=\"1400\">Press <span class=\"xzb\" data-key=\"menu\"><img class=\"xzb-g\" src=\"assets/buttons/menu.svg\" alt=\"\" width=\"60.86\" height=\"32\"><span class=\"xzb-n\">MENU<\/span><\/span><\/li><li data-t=\"1900\">Press <span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span><\/li><\/ol><\/li><\/ol><\/div>\n<div class=\"mg\" id=\"f-browse-10\" data-iface=\"modern\"><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/2f012356f15245ab.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The tag list with 12 of 100 tracks, one row touched\"><img src=\"manual/shots/2f012356f15245ab.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The tag list with 12 of 100 tracks, one row touched<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/6b8a43b27ef5d87a.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The tag list full at 100 tracks\"><img src=\"manual/shots/6b8a43b27ef5d87a.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The tag list full at 100 tracks<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/6e557c9773a57996.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: MENU in the tag list: REMOVE FROM TAG LIST, CREATE PLAYLIST and REMOVE ALL TRACKS\"><img src=\"manual/shots/6e557c9773a57996.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>MENU in the tag list: REMOVE FROM TAG LIST, CREATE PLAYLIST and REMOVE ALL TRACKS<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/ec448da98853ee99.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: CREATE PLAYLIST: the tag list saved as a new playlist\"><img src=\"manual/shots/ec448da98853ee99.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>CREATE PLAYLIST: the tag list saved as a new playlist<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/9484a938cae77156.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: REMOVE ALL TRACKS armed: push again to clear the tag list\"><img src=\"manual/shots/9484a938cae77156.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>REMOVE ALL TRACKS armed: push again to clear the tag list<\/figcaption><\/figure><\/div>\n<h4 id=\"m-playlists\" data-anchor=\"playlists\" data-iface=\"modern\">Playlists <span class=\"tag tag--modern\">modern<\/span><\/h4>\n<p>Tap <strong>PLAYLIST<\/strong> in the BROWSE category rail, or on the SHORTCUT screen, to open the USB's playlists. You can also make your own and change them on the player. Press <span class=\"xzb\" data-key=\"menu\"><img class=\"xzb-g\" src=\"assets/buttons/menu.svg\" alt=\"\" width=\"60.86\" height=\"32\"><span class=\"xzb-n\">MENU<\/span><\/span> in the playlist list or inside a playlist.<\/p>\n<div class=\"mn\" data-iface=\"modern\" role=\"group\" aria-label=\"Playlists\"><ol class=\"mn-scenes\"><li data-flow=\"playlists\" data-video=\"assets/manual/nav/playlists.mp4\" data-poster=\"assets/manual/nav/playlists.webp\" data-w=\"1280\" data-h=\"480\" data-seconds=\"5.112\" data-title=\"Playlists\"><ol class=\"mn-steps\"><li data-t=\"500\">Press <span class=\"xzb\" data-key=\"browse\"><img class=\"xzb-g\" src=\"assets/buttons/browse.svg\" alt=\"\" width=\"79.98\" height=\"32\"><span class=\"xzb-n\">BROWSE<\/span><\/span><\/li><li data-t=\"1000\">Turn <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span> 6 clicks clockwise, then push it<\/li><li data-t=\"2700\">Turn <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span> 2 clicks clockwise, then push it<\/li><li data-t=\"3600\">Press <span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span><\/li><\/ol><\/li><\/ol><\/div>\n<div class=\"table\"><table><thead><tr><th>In the MENU panel<\/th><th>What it does<\/th><\/tr><\/thead><tbody><tr><td>NEW PLAYLIST<\/td><td>Makes a playlist in the folder that is open. Type its name on the keyboard<\/td><\/tr><tr><td>RENAME<\/td><td>Renames the highlighted playlist<\/td><\/tr><tr><td>DELETE<\/td><td>Deletes the highlighted playlist. Push again to confirm<\/td><\/tr><tr><td>ADD TO PLAYLIST<\/td><td>Adds the highlighted track to a playlist you pick<\/td><\/tr><tr><td>REMOVE FROM PLAYLIST<\/td><td>Takes the highlighted track out of the playlist<\/td><\/tr><tr><td>MOVE TRACK<\/td><td>Picks up a track. Turn the encoder to move it, push to drop it<\/td><\/tr><\/tbody><\/table><\/div>\n<p>Playlists, the tag list, played marks and histories can change only on a USB that is not read-only. Changes made on the player are saved on the same USB in <code>XZMODS/playlists.txt<\/code>. They never change the library your DJ software exported, so your DJ software and the CLASSIC browse screens do not show them. A playlist you changed on the player is marked in the list. In HISTORY the <span class=\"xzb\" data-key=\"menu\"><img class=\"xzb-g\" src=\"assets/buttons/menu.svg\" alt=\"\" width=\"60.86\" height=\"32\"><span class=\"xzb-n\">MENU<\/span><\/span> panel offers DELETE HISTORY and DELETE ALL HISTORIES, each after a second push. If the USB is read-only you see <strong>THIS STICK IS READ-ONLY: PLAYLISTS CANNOT CHANGE<\/strong>. If it is full you see <strong>THE STICK IS FULL: PLAYLIST NOT SAVED<\/strong>.<\/p>\n<figure class=\"mf\" id=\"f-browse-11\" data-iface=\"modern\"><div class=\"mf-frame\"><div class=\"mf-bar\"><span class=\"mf-label\">PLAYLIST · MENU<\/span><\/div><div class=\"mf-stage\"><img src=\"manual/shots/5eed7e5557fc0974.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"The playlist list with its MENU panel open and DELETE highlighted.\"><span class=\"mf-spot\" aria-hidden=\"true\"><\/span><div class=\"mf-marks\" role=\"group\" aria-label=\"Numbered points on the picture\"><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"1\" data-x=\"76.500\" data-y=\"62.917\" aria-label=\"1: PLAYLIST\" aria-describedby=\"f-browse-11-1\">1<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"2\" data-x=\"86.250\" data-y=\"69.583\" aria-label=\"2: NEW PLAYLIST\" aria-describedby=\"f-browse-11-2\">2<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"3\" data-x=\"80.000\" data-y=\"76.667\" aria-label=\"3: RENAME\" aria-describedby=\"f-browse-11-3\">3<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"4\" data-x=\"81.250\" data-y=\"83.750\" aria-label=\"4: DELETE\" aria-describedby=\"f-browse-11-4\">4<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"5\" data-x=\"68.125\" data-y=\"37.500\" aria-label=\"5: Sort and columns\" aria-describedby=\"f-browse-11-5\">5<\/button><\/div><\/div><\/div><figcaption>The playlist list with its MENU panel open and DELETE highlighted.<\/figcaption><ol class=\"mf-legend\" aria-label=\"What the numbers show\"><li data-n=\"1\" id=\"f-browse-11-1\"><span class=\"mf-chip\" aria-hidden=\"true\">1<\/span><div><b>PLAYLIST<\/b> <span>Actions for the playlist list.<\/span><\/div><\/li><li data-n=\"2\" id=\"f-browse-11-2\"><span class=\"mf-chip\" aria-hidden=\"true\">2<\/span><div><b>NEW PLAYLIST<\/b> <span>Makes a playlist here.<\/span><\/div><\/li><li data-n=\"3\" id=\"f-browse-11-3\"><span class=\"mf-chip\" aria-hidden=\"true\">3<\/span><div><b>RENAME<\/b> <span>Renames the highlighted playlist.<\/span><\/div><\/li><li data-n=\"4\" id=\"f-browse-11-4\"><span class=\"mf-chip\" aria-hidden=\"true\">4<\/span><div><b>DELETE<\/b> <span>Deletes it after a second push.<\/span><\/div><\/li><li data-n=\"5\" id=\"f-browse-11-5\"><span class=\"mf-chip\" aria-hidden=\"true\">5<\/span><div><b>Sort and columns<\/b> <span>The same sort and column choices as in BROWSE.<\/span><\/div><\/li><\/ol><\/figure>\n<div class=\"mg\" id=\"f-browse-12\" data-iface=\"modern\"><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/2491adfd681b3b83.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: A playlist&#x27;s tracks\"><img src=\"manual/shots/2491adfd681b3b83.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>A playlist's tracks<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/ae52e7ce0e98c848.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Playlist folders\"><img src=\"manual/shots/ae52e7ce0e98c848.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Playlist folders<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/3897a541e9eddc1d.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: DELETE armed: push again to delete\"><img src=\"manual/shots/3897a541e9eddc1d.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>DELETE armed: push again to delete<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/300aeb490bd5c643.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Naming a new playlist on the keyboard\"><img src=\"manual/shots/300aeb490bd5c643.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Naming a new playlist on the keyboard<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/5963f31459431f7b.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: ADD TO PLAYLIST: pick the playlist\"><img src=\"manual/shots/5963f31459431f7b.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>ADD TO PLAYLIST: pick the playlist<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/1ff4ef7fe7d32d20.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: A track picked up to move\"><img src=\"manual/shots/1ff4ef7fe7d32d20.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>A track picked up to move<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/f55c824a816b0a53.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: A playlist changed on the player, marked in the list\"><img src=\"manual/shots/f55c824a816b0a53.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>A playlist changed on the player, marked in the list<\/figcaption><\/figure><\/div>\n<h3 id=\"m-source\" data-anchor=\"source\" data-iface=\"modern\">SOURCE <span class=\"tag tag--modern\">modern<\/span><\/h3>\n<p>SOURCE shows every place music can come from, one tile each, named as the player's own source keys are printed: <strong>USB 1<\/strong>, <strong>USB 2<\/strong>, <strong>LINK<\/strong> and the library link from a computer or phone. A bar under the tiles says what the <strong>REAR USB<\/strong> port is used for. Press <span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span> at the top of a list, tap the source tile at the top left of BROWSE, or press the USB 1 or USB 2 key while that stick is not ready.<\/p>\n<div class=\"mn\" data-iface=\"modern\" role=\"group\" aria-label=\"SOURCE\"><ol class=\"mn-scenes\"><li data-flow=\"source\" data-video=\"assets/manual/nav/source.mp4\" data-poster=\"assets/manual/nav/source.webp\" data-w=\"1280\" data-h=\"480\" data-seconds=\"2.712\" data-title=\"SOURCE\"><ol class=\"mn-steps\"><li data-t=\"500\">Open SOURCE (<span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span> at the top of a list)<\/li><li data-t=\"1000\">Turn <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span> 1 click clockwise<\/li><li data-t=\"1200\">Press <span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span><\/li><\/ol><\/li><\/ol><\/div>\n<figure class=\"mf\" id=\"f-browse-13\" data-iface=\"modern\"><div class=\"mf-frame\"><div class=\"mf-bar\"><span class=\"mf-label\">SOURCE<\/span><\/div><div class=\"mf-stage\"><img src=\"manual/shots/ef036f1fb7b681de.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"USB 1 is being browsed and plays on decks 1 and 2. USB 2 is still loading. No loopback cable is in, so the rear USB port is free for a computer.\"><span class=\"mf-spot\" aria-hidden=\"true\"><\/span><div class=\"mf-marks\" role=\"group\" aria-label=\"Numbered points on the picture\"><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"1\" data-x=\"11.875\" data-y=\"14.167\" aria-label=\"1: BROWSING\" aria-describedby=\"f-browse-13-1\">1<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"2\" data-x=\"12.500\" data-y=\"47.083\" aria-label=\"2: Name and colour\" aria-describedby=\"f-browse-13-2\">2<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"3\" data-x=\"41.250\" data-y=\"42.708\" aria-label=\"3: Status\" aria-describedby=\"f-browse-13-3\">3<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"4\" data-x=\"14.375\" data-y=\"56.250\" aria-label=\"4: FREE\" aria-describedby=\"f-browse-13-4\">4<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"5\" data-x=\"13.750\" data-y=\"68.750\" aria-label=\"5: DECK\" aria-describedby=\"f-browse-13-5\">5<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"6\" data-x=\"70.625\" data-y=\"53.333\" aria-label=\"6: LINK\" aria-describedby=\"f-browse-13-6\">6<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"7\" data-x=\"95.000\" data-y=\"59.375\" aria-label=\"7: REKORDBOX OVER LAN and OVER USB\" aria-describedby=\"f-browse-13-7\">7<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"8\" data-x=\"55.750\" data-y=\"4.583\" aria-label=\"8: Hint\" aria-describedby=\"f-browse-13-8\">8<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"9\" data-x=\"20.000\" data-y=\"77.917\" aria-label=\"9: REAR USB\" aria-describedby=\"f-browse-13-9\">9<\/button><\/div><\/div><\/div><figcaption>USB 1 is being browsed and plays on decks 1 and 2. USB 2 is still loading. No loopback cable is in, so the rear USB port is free for a computer.<\/figcaption><ol class=\"mf-legend\" aria-label=\"What the numbers show\"><li data-n=\"1\" id=\"f-browse-13-1\"><span class=\"mf-chip\" aria-hidden=\"true\">1<\/span><div><b>BROWSING<\/b> <span>The source BROWSE shows now.<\/span><\/div><\/li><li data-n=\"2\" id=\"f-browse-13-2\"><span class=\"mf-chip\" aria-hidden=\"true\">2<\/span><div><b>Name and colour<\/b> <span>The USB's name and the colour saved on it.<\/span><\/div><\/li><li data-n=\"3\" id=\"f-browse-13-3\"><span class=\"mf-chip\" aria-hidden=\"true\">3<\/span><div><b>Status<\/b> <span>READY, LOADING, CAN'T READ, DECK 3/4 CABLE or NO REKORDBOX USB. See the table below.<\/span><\/div><\/li><li data-n=\"4\" id=\"f-browse-13-4\"><span class=\"mf-chip\" aria-hidden=\"true\">4<\/span><div><b>FREE<\/b> <span>Free space on the USB, with a bar for how full it is.<\/span><\/div><\/li><li data-n=\"5\" id=\"f-browse-13-5\"><span class=\"mf-chip\" aria-hidden=\"true\">5<\/span><div><b>DECK<\/b> <span>The decks playing a track from this stick.<\/span><\/div><\/li><li data-n=\"6\" id=\"f-browse-13-6\"><span class=\"mf-chip\" aria-hidden=\"true\">6<\/span><div><b>LINK<\/b> <span>Linked players over the LAN port, and DJ software over the rear USB port. Opens the player's own screen.<\/span><\/div><\/li><li data-n=\"7\" id=\"f-browse-13-7\"><span class=\"mf-chip\" aria-hidden=\"true\">7<\/span><div><b>REKORDBOX OVER LAN and OVER USB<\/b> <span>A library shared from a computer or phone, over the LAN port or the rear USB port. Opens the player's own screen.<\/span><\/div><\/li><li data-n=\"8\" id=\"f-browse-13-8\"><span class=\"mf-chip\" aria-hidden=\"true\">8<\/span><div><b>Hint<\/b> <span>What opening the highlighted tile does, or why it cannot open.<\/span><\/div><\/li><li data-n=\"9\" id=\"f-browse-13-9\"><span class=\"mf-chip\" aria-hidden=\"true\">9<\/span><div><b>REAR USB<\/b> <span>What the rear USB port holds now, and what that means.<\/span><\/div><\/li><\/ol><\/figure>\n<p>Turn the encoder to pick a tile and push to open it. Touch a tile once to highlight it and again to open it. A USB stick opens its library in BROWSE. LINK and the library link open the player's own screen: push the encoder for those, because touch cannot open them yet. A tile that cannot open is skipped.<\/p>\n<p>The player's source keys answer in MODERN too. <strong>USB 1<\/strong> or <strong>USB 2<\/strong> opens that stick's library in BROWSE when it is ready, and SOURCE with that tile highlighted when it is not. <span class=\"xzb\" data-key=\"link\"><img class=\"xzb-g\" src=\"assets/buttons/link.svg\" alt=\"\" width=\"54.02\" height=\"32\"><span class=\"xzb-n\">LINK<\/span><\/span> opens SOURCE with the LINK tile highlighted; press it again to open the player's own LINK screen. While the player's own screen is up, for example after that second press, USB 1, USB 2 or <span class=\"xzb\" data-key=\"link\"><img class=\"xzb-g\" src=\"assets/buttons/link.svg\" alt=\"\" width=\"54.02\" height=\"32\"><span class=\"xzb-n\">LINK<\/span><\/span> brings MODERN back with that key's screen.<\/p>\n<div class=\"table\"><table><thead><tr><th>A USB tile says<\/th><th>What it means<\/th><\/tr><\/thead><tbody><tr><td>READY<\/td><td>Its library is read. Open it to browse.<\/td><\/tr><tr><td>LOADING<\/td><td>The player is still reading its library.<\/td><\/tr><tr><td>CAN'T READ<\/td><td>The stick is in, but its library could not be read. Export the library to it again.<\/td><\/tr><tr><td>DECK 3/4 CABLE<\/td><td>This top port holds the loopback cable for decks 3 and 4, not music.<\/td><\/tr><tr><td>NO REKORDBOX USB<\/td><td>No stick with an exported library is in this port. A phone, or a stick without a library, shows this too.<\/td><\/tr><\/tbody><\/table><\/div>\n<p>The <strong>REAR USB<\/strong> bar follows the loopback cable for <a class=\"m-link\" href=\"#manual\" data-chapter=\"four-decks\">decks 3 and 4<\/a>:<\/p>\n<div class=\"table\"><table><thead><tr><th>The bar says<\/th><th>What it means<\/th><\/tr><\/thead><tbody><tr><td>DECK 3/4 CABLE<\/td><td>Decks 3 and 4 play through this port. While the cable is in, DJ software and rekordbox over a USB cable cannot connect there. Linked players and rekordbox over LAN still work. The LINK and library tiles mark their USB half with an amber cross and REAR USB IN USE.<\/td><\/tr><tr><td>DECKS 3/4 STARTING<\/td><td>Decks 3 and 4 are starting.<\/td><\/tr><tr><td>DECKS 3/4 STOPPED<\/td><td>Decks 3 and 4 could not start. The bar gives the reason.<\/td><\/tr><tr><td>NO DECK 3/4 CABLE<\/td><td>A computer can use this port. Decks 3 and 4 need the loopback cable here, from a top USB port.<\/td><\/tr><tr><td>FOR A COMPUTER<\/td><td>Four decks are not installed on this USB loader. A computer connects here.<\/td><\/tr><\/tbody><\/table><\/div>\n<div class=\"mg\" id=\"f-browse-14\" data-iface=\"modern\"><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/5e341923f71711b3.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The loopback cable in USB 2: decks 3 and 4 play through the rear USB port\"><img src=\"manual/shots/5e341923f71711b3.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The loopback cable in USB 2: decks 3 and 4 play through the rear USB port<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/83e9be2518034c6f.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The library link with the cable in: over LAN only\"><img src=\"manual/shots/83e9be2518034c6f.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The library link with the cable in: over LAN only<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/fd791846be708db0.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: USB 2 highlighted while it holds the cable\"><img src=\"manual/shots/fd791846be708db0.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>USB 2 highlighted while it holds the cable<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/040e4b7e729a9d59.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The cable in, and no music stick in the other port\"><img src=\"manual/shots/040e4b7e729a9d59.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The cable in, and no music stick in the other port<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/624328796b0fb280.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Decks 3 and 4 starting\"><img src=\"manual/shots/624328796b0fb280.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Decks 3 and 4 starting<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/77207bc4e1d95248.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Decks 3 and 4 could not start\"><img src=\"manual/shots/77207bc4e1d95248.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Decks 3 and 4 could not start<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/86416b5091dc6561.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: A stick whose library cannot be read\"><img src=\"manual/shots/86416b5091dc6561.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>A stick whose library cannot be read<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/5d9c3cc9379dafb0.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Nothing connected\"><img src=\"manual/shots/5d9c3cc9379dafb0.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Nothing connected<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/83e686fa26de127f.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: LINK handled by the player&#x27;s own screen\"><img src=\"manual/shots/83e686fa26de127f.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>LINK handled by the player's own screen<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/5440520caa7a36d7.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The library link handled by the player&#x27;s own screen\"><img src=\"manual/shots/5440520caa7a36d7.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The library link handled by the player's own screen<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/babcc2f3f8686dae.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Before the sources have been read\"><img src=\"manual/shots/babcc2f3f8686dae.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Before the sources have been read<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/fb6ae10b25407bca.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: SOURCE opened before anything has been read\"><img src=\"manual/shots/fb6ae10b25407bca.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>SOURCE opened before anything has been read<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/f81725c51cd586ac.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: SOURCE reached with BACK from the top of BROWSE\"><img src=\"manual/shots/f81725c51cd586ac.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>SOURCE reached with <span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span> from the top of BROWSE<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/9a9c3466902d0b0b.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: USB 2 asked for with nothing in it\"><img src=\"manual/shots/9a9c3466902d0b0b.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>USB 2 asked for with nothing in it<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/3e42c6c4ae2ffd8f.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: BROWSE on a USB that has been removed: no old rows remain\"><img src=\"manual/shots/3e42c6c4ae2ffd8f.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>BROWSE on a USB that has been removed: no old rows remain<\/figcaption><\/figure><\/div>\n<h3 id=\"m-info\" data-anchor=\"info\" data-iface=\"modern\">INFO <span class=\"tag tag--modern\">modern<\/span><\/h3>\n<p>Press <span class=\"xzb\" data-key=\"info\"><img class=\"xzb-g\" src=\"assets/buttons/info.svg\" alt=\"\" width=\"54.02\" height=\"32\"><span class=\"xzb-n\">INFO<\/span><\/span> on the play screen, or tap the INFO icon in the top bar, to see everything about a loaded track.<\/p>\n<figure class=\"mf\" id=\"f-browse-15\" data-iface=\"modern\"><div class=\"mf-frame\"><div class=\"mf-bar\"><span class=\"mf-label\">INFO<\/span><\/div><div class=\"mf-stage\"><img src=\"manual/shots/266915ee38899d08.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"INFO for deck 1&#x27;s track.\"><span class=\"mf-spot\" aria-hidden=\"true\"><\/span><div class=\"mf-marks\" role=\"group\" aria-label=\"Numbered points on the picture\"><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"1\" data-x=\"32.250\" data-y=\"4.583\" aria-label=\"1: Deck tabs\" aria-describedby=\"f-browse-15-1\">1<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"2\" data-x=\"76.250\" data-y=\"4.583\" aria-label=\"2: Close\" aria-describedby=\"f-browse-15-2\">2<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"3\" data-x=\"28.125\" data-y=\"31.250\" aria-label=\"3: Artwork\" aria-describedby=\"f-browse-15-3\">3<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"4\" data-x=\"27.750\" data-y=\"57.292\" aria-label=\"4: RATING\" aria-describedby=\"f-browse-15-4\">4<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"5\" data-x=\"49.375\" data-y=\"26.667\" aria-label=\"5: Linked field\" aria-describedby=\"f-browse-15-5\">5<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"6\" data-x=\"47.375\" data-y=\"47.917\" aria-label=\"6: KEY and BPM\" aria-describedby=\"f-browse-15-6\">6<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"7\" data-x=\"67.500\" data-y=\"70.833\" aria-label=\"7: COMMENT\" aria-describedby=\"f-browse-15-7\">7<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"8\" data-x=\"13.750\" data-y=\"77.083\" aria-label=\"8: SOURCE\" aria-describedby=\"f-browse-15-8\">8<\/button><button class=\"mf-mark\" type=\"button\" tabindex=\"-1\" data-n=\"9\" data-x=\"25.000\" data-y=\"90.833\" aria-label=\"9: Deck strip\" aria-describedby=\"f-browse-15-9\">9<\/button><\/div><\/div><\/div><figcaption>INFO for deck 1's track.<\/figcaption><ol class=\"mf-legend\" aria-label=\"What the numbers show\"><li data-n=\"1\" id=\"f-browse-15-1\"><span class=\"mf-chip\" aria-hidden=\"true\">1<\/span><div><b>Deck tabs<\/b> <span>Switch between the decks' tracks.<\/span><\/div><\/li><li data-n=\"2\" id=\"f-browse-15-2\"><span class=\"mf-chip\" aria-hidden=\"true\">2<\/span><div><b>Close<\/b> <span>Back to where you were. <span class=\"xzb\" data-key=\"info\"><img class=\"xzb-g\" src=\"assets/buttons/info.svg\" alt=\"\" width=\"54.02\" height=\"32\"><span class=\"xzb-n\">INFO<\/span><\/span> and <span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span> close it too.<\/span><\/div><\/li><li data-n=\"3\" id=\"f-browse-15-3\"><span class=\"mf-chip\" aria-hidden=\"true\">3<\/span><div><b>Artwork<\/b> <span>The track's artwork, when the USB has it.<\/span><\/div><\/li><li data-n=\"4\" id=\"f-browse-15-4\"><span class=\"mf-chip\" aria-hidden=\"true\">4<\/span><div><b>RATING<\/b> <span>The track's stars.<\/span><\/div><\/li><li data-n=\"5\" id=\"f-browse-15-5\"><span class=\"mf-chip\" aria-hidden=\"true\">5<\/span><div><b>Linked field<\/b> <span>A field with an arrow opens BROWSE with every track that shares it. ARTIST, ALBUM, KEY, BPM and GENRE are linked.<\/span><\/div><\/li><li data-n=\"6\" id=\"f-browse-15-6\"><span class=\"mf-chip\" aria-hidden=\"true\">6<\/span><div><b>KEY and BPM<\/b> <span>Tap to open the KEY or BPM category at this value.<\/span><\/div><\/li><li data-n=\"7\" id=\"f-browse-15-7\"><span class=\"mf-chip\" aria-hidden=\"true\">7<\/span><div><b>COMMENT<\/b> <span>The comment saved with the track in your DJ software.<\/span><\/div><\/li><li data-n=\"8\" id=\"f-browse-15-8\"><span class=\"mf-chip\" aria-hidden=\"true\">8<\/span><div><b>SOURCE<\/b> <span>Where the track came from.<\/span><\/div><\/li><li data-n=\"9\" id=\"f-browse-15-9\"><span class=\"mf-chip\" aria-hidden=\"true\">9<\/span><div><b>Deck strip<\/b> <span>Both decks stay in view.<\/span><\/div><\/li><\/ol><\/figure>\n<div class=\"mg\" id=\"f-browse-16\" data-iface=\"modern\"><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/01c43e8eced78f08.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Deck 2&#x27;s track with a long title\"><img src=\"manual/shots/01c43e8eced78f08.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Deck 2's track with a long title<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/90c9e4acdb419fd6.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The highlight on KEY, ready to push\"><img src=\"manual/shots/90c9e4acdb419fd6.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The highlight on KEY, ready to push<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/dc4c3753a2c49992.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: The highlight on GENRE\"><img src=\"manual/shots/dc4c3753a2c49992.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>The highlight on GENRE<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/6f64aa9b512c31d5.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: INFO for the track highlighted in a list, in its own tab\"><img src=\"manual/shots/6f64aa9b512c31d5.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>INFO for the track highlighted in a list, in its own tab<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/b51ab9e161d20002.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: A deck with no track\"><img src=\"manual/shots/b51ab9e161d20002.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>A deck with no track<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/31dee6d5cbc002ae.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: INFO when browsing is not available: fields are not linked\"><img src=\"manual/shots/31dee6d5cbc002ae.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>INFO when browsing is not available: fields are not linked<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/29cacd3d314f0f9a.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: Long names cut to fit\"><img src=\"manual/shots/29cacd3d314f0f9a.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>Long names cut to fit<\/figcaption><\/figure><figure class=\"mg-item\"><button class=\"mg-shot\" type=\"button\" data-zoom=\"manual/shots/85e617eb27dfa206.webp\" data-w=\"800\" data-h=\"480\" aria-label=\"Enlarge: INFO opened before anything has been read\"><img src=\"manual/shots/85e617eb27dfa206.webp\" width=\"800\" height=\"480\" loading=\"lazy\" decoding=\"async\" alt=\"\"><\/button><figcaption>INFO opened before anything has been read<\/figcaption><\/figure><\/div>\n<h3 id=\"m-browsing-in-classic\" data-anchor=\"browsing-in-classic\" data-iface=\"classic\">Browsing in CLASSIC <span class=\"tag tag--classic\">classic<\/span><\/h3>\n<p>CLASSIC keeps the player's own browse screens: the same lists, keys and menus the XDJ-XZ operating instructions describe. XZ Mods adds three things to them.<\/p>\n<ul><li><strong>The key in every row.<\/strong> Each track row shows up to three fields from the library exported to your USB inside the title cell. The default is the title, then the key, then the BPM.<\/li><li><strong>Key before title.<\/strong> With <strong>KEY BEFORE TITLE<\/strong> on, the key leads the row, so you can read keys down the list.<\/li><li><strong>Key match colours.<\/strong> With <strong>KEY MATCH COLOURS<\/strong> on, a leading key is green when it mixes with the master deck's key, amber when it is detuned against it, and grey otherwise.<\/li><\/ul>\n<p>The table header names what the player's own <span class=\"xzb\" data-key=\"menu\"><img class=\"xzb-g\" src=\"assets/buttons/menu.svg\" alt=\"\" width=\"60.86\" height=\"32\"><span class=\"xzb-n\">MENU<\/span><\/span> click changes: <strong>SORT<\/strong> over the title column and <strong>COLUMN<\/strong> over the right-hand column. The STEMS and MODS buttons stay at the top right.<\/p>\n<p>These additions only use tracks on a USB with an exported library. A track XZ Mods cannot match in the export keeps the player's own row, and a field the export does not have is left out.<\/p>\n<h3 id=\"m-browse-settings\" data-anchor=\"browse-settings\">Browse settings<\/h3>\n<div class=\"mn\" data-iface=\"modern\" role=\"group\" aria-label=\"Browse settings\"><ol class=\"mn-scenes\"><li data-flow=\"nav-a-browse-settings\" data-video=\"assets/manual/nav/nav-a-browse-settings.mp4\" data-poster=\"assets/manual/nav/nav-a-browse-settings.webp\" data-w=\"1280\" data-h=\"480\" data-seconds=\"6.112\" data-title=\"Browse settings\"><ol class=\"mn-steps\"><li data-t=\"500\">Press <span class=\"xzb\" data-key=\"menu\"><img class=\"xzb-g\" src=\"assets/buttons/menu.svg\" alt=\"\" width=\"60.86\" height=\"32\"><span class=\"xzb-n\">MENU<\/span><\/span><\/li><li data-t=\"1000\">Tap <strong>SCREEN<\/strong><\/li><li data-t=\"1520\">Tap <strong>KEY MATCH COLOURS<\/strong><\/li><li data-t=\"2040\">Tap <strong>KEY BEFORE TITLE<\/strong><\/li><li data-t=\"2560\">Tap <strong>CLOSE<\/strong><\/li><li data-t=\"3080\">Press <span class=\"xzb\" data-key=\"browse\"><img class=\"xzb-g\" src=\"assets/buttons/browse.svg\" alt=\"\" width=\"79.98\" height=\"32\"><span class=\"xzb-n\">BROWSE<\/span><\/span><\/li><li data-t=\"3580\">Push <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span><\/li><li data-t=\"4080\">Press <span class=\"xzb\" data-key=\"menu\"><img class=\"xzb-g\" src=\"assets/buttons/menu.svg\" alt=\"\" width=\"60.86\" height=\"32\"><span class=\"xzb-n\">MENU<\/span><\/span><\/li><li data-t=\"4580\">Tap <strong>ARTIST<\/strong><\/li><\/ol><\/li><\/ol><\/div>\n<div class=\"table\"><table><thead><tr><th>Setting<\/th><th>MODS<\/th><th>What it does<\/th><th>Default<\/th><\/tr><\/thead><tbody><tr><td><code>browse_preview<\/code><\/td><td>PREVIEW tile in MODERN browse<\/td><td>Shows the preview waveform column in MODERN browse<\/td><td>Hidden<\/td><\/tr><tr><td><code>browse_traffic<\/code><\/td><td><strong>SCREEN<\/strong>, KEY MATCH COLOURS<\/td><td>Colours keys that mix with the master deck's key, in both interfaces<\/td><td>On<\/td><\/tr><tr><td><code>browse_key_prefix<\/code><\/td><td><strong>SCREEN<\/strong>, KEY BEFORE TITLE<\/td><td>Puts the key first in each CLASSIC browse row<\/td><td>On<\/td><\/tr><tr><td><code>browse_1<\/code>, <code>browse_2<\/code>, <code>browse_3<\/code><\/td><td>none<\/td><td>The three fields in each CLASSIC browse row, in order. Each is TITLE, ARTIST, KEY or BPM<\/td><td>TITLE, KEY, BPM<\/td><\/tr><tr><td><code>modern_browse_columns<\/code><\/td><td>COLUMNS in the MODERN <span class=\"xzb\" data-key=\"menu\"><img class=\"xzb-g\" src=\"assets/buttons/menu.svg\" alt=\"\" width=\"60.86\" height=\"32\"><span class=\"xzb-n\">MENU<\/span><\/span> panel<\/td><td>The columns of the MODERN track list. TITLE always shows<\/td><td>Automatic<\/td><\/tr><\/tbody><\/table><\/div>\n<p>MODS has no control for the three CLASSIC row fields in this version. They keep the values stored on the USB. In MODERN, choose columns from the <span class=\"xzb\" data-key=\"menu\"><img class=\"xzb-g\" src=\"assets/buttons/menu.svg\" alt=\"\" width=\"60.86\" height=\"32\"><span class=\"xzb-n\">MENU<\/span><\/span> panel instead.<\/p>\n<h3 id=\"m-if-browsing-goes-wrong\" data-anchor=\"if-browsing-goes-wrong\">If browsing goes wrong<\/h3>\n<div class=\"mn\" data-iface=\"modern\" role=\"group\" aria-label=\"If browsing goes wrong\"><ol class=\"mn-scenes\"><li data-flow=\"nav-a-browse-recovery\" data-video=\"assets/manual/nav/nav-a-browse-recovery.mp4\" data-poster=\"assets/manual/nav/nav-a-browse-recovery.webp\" data-w=\"1280\" data-h=\"480\" data-seconds=\"4.212\" data-title=\"If browsing goes wrong\"><ol class=\"mn-steps\"><li data-t=\"500\">Open SOURCE (<span class=\"xzb\" data-key=\"back\"><img class=\"xzb-g\" src=\"assets/buttons/back.svg\" alt=\"\" width=\"76.49\" height=\"32\"><span class=\"xzb-n\">BACK<\/span><\/span> at the top of a list)<\/li><li data-t=\"1000\">Turn <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span> 1 click clockwise, then push it<\/li><li data-t=\"1700\">Press <span class=\"xzb\" data-key=\"browse\"><img class=\"xzb-g\" src=\"assets/buttons/browse.svg\" alt=\"\" width=\"79.98\" height=\"32\"><span class=\"xzb-n\">BROWSE<\/span><\/span><\/li><li data-t=\"2200\">Push <span class=\"xzb\" data-key=\"rotary\"><img class=\"xzb-g\" src=\"assets/buttons/rotary.svg\" alt=\"\" width=\"33\" height=\"32\"><span class=\"xzb-n\">ROTARY SELECTOR<\/span><\/span><\/li><li data-t=\"2700\">Press <span class=\"xzb\" data-key=\"load\"><img class=\"xzb-g\" src=\"assets/buttons/load.svg\" alt=\"\" width=\"100.66\" height=\"32\"><span class=\"xzb-n\">LOAD<\/span><\/span> 1<\/li><\/ol><\/li><\/ol><\/div>\n<div class=\"table\"><table><thead><tr><th>You see<\/th><th>What to do<\/th><\/tr><\/thead><tbody><tr><td>USB1 IS NOT CONNECTED or USB2 IS NOT CONNECTED<\/td><td>Insert the USB, or pick another source<\/td><\/tr><tr><td>USB SOURCE CHANGED: SELECT TRACK AGAIN<\/td><td>The USB changed while you chose. Highlight the track again<\/td><\/tr><tr><td>LOAD LOCK: DECK 1 IS PLAYING (or another deck)<\/td><td>LOAD LOCK is on and that deck plays. Pause it, or turn LOAD LOCK off in UTILITY<\/td><\/tr><tr><td>USB STARTING / DECK 1 LOADS WHEN READY (or DECK 2)<\/td><td>The stick went in a moment ago. Wait: the track loads by itself when the player is ready<\/td><\/tr><tr><td>THAT DECK CANNOT LOAD THIS TRACK<\/td><td>Load it on another deck<\/td><\/tr><tr><td>LOAD FROM THIS LIST IS OFF<\/td><td>Load from a track list instead<\/td><\/tr><tr><td>LINK BROWSING IS NOT AVAILABLE YET or COMPUTER BROWSING IS NOT AVAILABLE YET<\/td><td>Switch to CLASSIC to browse that source<\/td><\/tr><tr><td>TOUCH CANNOT OPEN THIS YET: PUSH THE ENCODER<\/td><td>Highlight the tile and push the encoder<\/td><\/tr><tr><td>PLAYLIST CHANGE NOT APPLIED<\/td><td>Try again. If the USB is read-only or full, the notice says so<\/td><\/tr><\/tbody><\/table><\/div>";
